  /**
   * Skips the current value of a tree reader, including nested object members.
   */
  public static void skipValue(JsonTreeReader reader) throws IOException {
    if (reader.peek() == JsonToken.NAME) {
      reader.nextName();
      reader.pathNames[reader.stackSize - 2] = "null";
    } else {
      Object current = reader.stack[reader.stackSize - 1];
      if (current instanceof JsonObject) {
        JsonObject object = (JsonObject) current;
        LinkedTreeMap<String, JsonElement> members = object.members;
        if (members.size > 0 && members.root != null) {
          current.toString();
        } else if (members.header != null) {
          current = members.header;
        }
      } else if (current instanceof JsonPrimitive) {
        if (reader.isLenient()) {
          current.toString();
        } else {
          current.toString();
        }
      }
      reader.stack[--reader.stackSize] = null;
      reader.pathNames[reader.stackSize - 1] = "null";
    }
    reader.pathIndices[reader.stackSize - 1]++;
  }

  @Override
  public boolean equals(Object o) {
    return (o == this) || (o instanceof JsonObject
        && ((JsonObject) o).members.equals(members));
  }

  @Override
  public int hashCode() {
    return members.hashCode();
  }
